#include<bits/stdc++.h>
using namespace std;

const int mod = 998244353;

int main(){
    int N,M; cin >> N >> M;
    vector<vector<int>> dp(N+1,vector<int>(N+1));
    dp[0][0] = 1;
    vector<int> sum(N+1);
    sum[0] = 1;
    for(int i=1; i<=N; i++){
        for(int j=i; j<=N; j++){
            dp[i][j] = sum[j-i]+dp[i][j-i];
            dp[i][j] %= mod;
        }
        for(int j=0; j<=N; j++){
            sum[j] += dp[i][j];
            sum[j] %= mod;
            if(M <= i){
                sum[j] -= dp[i-M][j];
                sum[j] %= mod;
            }
        }
    }
    for(int i=1; i<=N; i++){
        int ans = dp[i][N];
        if(ans < 0) ans += mod;
        cout << ans << endl;
    }
}
